"use client";

import { useEffect, useRef, useState } from "react";
import Script from "next/script";
import { useRouter } from "next/navigation";

export default function FacePage() {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const router = useRouter();

  const [loading, setLoading] = useState(true);
  const [authorized, setAuthorized] = useState(false);
  const [fadeOut, setFadeOut] = useState(false);

  // ---------------------
  // Fullscreen canvas size
  // ---------------------
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    function resize() {
      if(!canvas) return;
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }

    resize();
    window.addEventListener("resize", resize);
    return () => window.removeEventListener("resize", resize);
  }, []);

  // ---------------------
  // Loading → Authorized → Fade → Redirect
  // ---------------------
  useEffect(() => {
    const t1 = setTimeout(() => {
      setLoading(false);

      const t2 = setTimeout(() => {
        setAuthorized(true);

        const t3 = setTimeout(() => {
          setFadeOut(true);

          const t4 = setTimeout(() => {
            router.push("/dashboard");
          }, 900); // wait for fade animation

          return () => clearTimeout(t4);
        }, 1500);

        return () => clearTimeout(t3);
      }, 400);

      return () => clearTimeout(t2);
    }, 2000);

    return () => clearTimeout(t1);
  }, [router]);

  // ---------------------
  // MediaPipe setup
  // ---------------------
  useEffect(() => {
    if (!window.FaceMesh || !window.Camera) return;

    const video = videoRef.current!;
    const canvas = canvasRef.current!;
    const ctx = canvas.getContext("2d")!;

    const faceMesh = new window.FaceMesh({
      locateFile: (file: string) =>
        `https://cdn.jsdelivr.net/npm/@mediapipe/face_mesh/${file}`,
    });

    faceMesh.setOptions({
      maxNumFaces: 1,
      refineLandmarks: true,
      minDetectionConfidence: 0.5,
      minTrackingConfidence: 0.5,
    });

    faceMesh.onResults((results: any) => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(results.image, 0, 0, canvas.width, canvas.height);

      if (results.multiFaceLandmarks) {
        ctx.fillStyle = "#00eaff";
        for (const lm of results.multiFaceLandmarks) {
          for (const p of lm) {
            ctx.beginPath();
            ctx.arc(p.x * canvas.width, p.y * canvas.height, 2, 0, 2 * Math.PI);
            ctx.fill();
          }
        }
      }
    });

    const camera = new window.Camera(video, {
      onFrame: async () => await faceMesh.send({ image: video }),
      width: 1280,
      height: 720,
    });

    camera.start();
  }, []);

  return (
    <>
      {/* MediaPipe */}
      <Script src="https://cdn.jsdelivr.net/npm/@mediapipe/face_mesh/face_mesh.js" strategy="beforeInteractive" />
      <Script src="https://cdn.jsdelivr.net/npm/@mediapipe/camera_utils/camera_utils.js" strategy="beforeInteractive" />

      {/* Main screen */}
      <div
        style={{
          position: "fixed",
          inset: 0,
          overflow: "hidden",
          opacity: fadeOut ? 0 : 1,
          transition: "opacity 0.9s ease-in-out",
        }}
      >
        <video ref={videoRef} style={{ display: "none" }} />

        <canvas
          ref={canvasRef}
          style={{
            position: "absolute",
            inset: 0,
            width: "100vw",
            height: "100vh",
          }}
        />

        {/* Dim overlay */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: "rgba(0,0,0,0.35)",
            pointerEvents: "none",
          }}
        />

        {/* ------------------- */}
        {/* Creative Loading Animation */}
        {/* ------------------- */}
        {loading && (
          <div className="loadingWrap">
            <div className="morphDiamond">
              <div className="innerShape" />
            </div>
          </div>
        )}

        {/* ------------------- */}
        {/* Authorized Popup */}
        {/* ------------------- */}
        {authorized && (
          <div className="authorizedPopup">
            Authorized
          </div>
        )}
      </div>

      {/* CSS */}
      <style jsx>{`
        /* === UNIQUE MORPHING DIAMOND LOADER === */
        .loadingWrap {
          position: absolute;
          inset: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          backdrop-filter: blur(6px);
          z-index: 20;
        }

        .morphDiamond {
          width: 110px;
          height: 110px;
          background: linear-gradient(135deg, #00d0ff, #0066ff);
          clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);
          display: flex;
          align-items: center;
          justify-content: center;
          animation: pulseMorph 1.6s infinite ease-in-out;
          box-shadow: 0px 0px 25px #00baff;
        }

        .innerShape {
          width: 45px;
          height: 45px;
          background: white;
          opacity: 0.8;
          clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);
          animation: innerSpin 1.2s infinite linear;
        }

        @keyframes pulseMorph {
          0% { transform: scale(1); filter: brightness(0.9); }
          50% { transform: scale(1.25); filter: brightness(1.3); }
          100% { transform: scale(1); filter: brightness(0.9); }
        }

        @keyframes innerSpin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }

        /* === AUTH POPUP UPGRADED UI === */
        .authorizedPopup {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%, -50%) scale(0.8);
          padding: 25px 55px;
          font-size: 32px;
          color: #00ff88;
          background: rgba(0, 0, 0, 0.85);
          border: 2px solid #00ff88;
          border-radius: 14px;
          z-index: 30;

          animation:
            popupScale 0.45s ease-out forwards,
            glowPulse 1.4s infinite ease-in-out,
            electricBorder 1.2s infinite;
        }

        @keyframes popupScale {
          from { transform: translate(-50%, -50%) scale(0.5); opacity: 0; }
          to { transform: translate(-50%, -50%) scale(1); opacity: 1; }
        }

        @keyframes glowPulse {
          0% { box-shadow: 0 0 8px #00ff88; }
          50% { box-shadow: 0 0 22px #00ff88; }
          100% { box-shadow: 0 0 8px #00ff88; }
        }

        /* flickering cyber-edge effect */
        @keyframes electricBorder {
          0%, 100% { border-color: #00ff88; }
          20% { border-color: #00ffaa; }
          40% { border-color: #00ff66; }
          60% { border-color: #00ff99; }
          80% { border-color: #00ff55; }
        }
      `}</style>
    </>
  );
}
